type Entrada = { dado: string; em: number };
const cache = new Map<string, Entrada>();
let buscas = 0;

function consulta(chave: unknown[], agora: number, staleTime: number): string {
  const k = JSON.stringify(chave);
  const e = cache.get(k);
  if (e && agora - e.em < staleTime) return e.dado + ' (cache)';
  buscas++;
  const dado = 'v' + buscas;
  cache.set(k, { dado, em: agora });
  return dado + ' (rede)';
}

