let token = 'velho';
let renovacoes = 0;
let renovando: Promise<void> | null = null;
const espera = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

const servidor = async (usado: string) => (usado === 'novo' ? 200 : 401);

function renova(): Promise<void> {
  renovando ??= (async () => {
    renovacoes++;
    await espera(30);
    token = 'novo';
  })().finally(() => { renovando = null; });
  return renovando;
}

async function chama(rota: string): Promise<string> {
  let status = await servidor(token);
  if (status === 401) { await renova(); status = await servidor(token); }
  return rota + ' ' + status;
}

